{
  "timeline": [
    {
      "date": "1924-10-01",
      "headline": "Birth",
      "text": "James Earl Carter Jr. was born in Plains, Georgia, United States."
    },
    {
      "date": "1946-07-07",
      "headline": "Marriage",
      "text": "Jimmy Carter married Rosalynn Smith."
    },
    {
      "date": "1946",
      "headline": "Graduation from U.S. Naval Academy",
      "text": "Carter graduated from the United States Naval Academy in Annapolis, Maryland, with a Bachelor of Science degree."
    },
    {
      "date": "1963",
      "headline": "Georgia State Senate",
      "text": "Carter began serving in the Georgia State Senate, representing the 14th district."
    },
    {
      "date": "1967",
      "headline": "End of State Senate Term",
      "text": "Carter's term in the Georgia State Senate ended."
    },
    {
      "date": "1971-01-12",
      "headline": "Governor of Georgia",
      "text": "Carter was inaugurated as the 76th governor of Georgia."
    },
    {
      "date": "1975-01-14",
      "headline": "End of Governorship",
      "text": "Carter's term as governor of Georgia ended."
    },
    {
      "date": "1977-01-20",
      "headline": "President of the United States",
      "text": "Jimmy Carter was inaugurated as the 39th president of the United States."
    },
    {
      "date": "1978-09-17",
      "headline": "Camp David Accords",
      "text": "Carter brokered the Camp David Accords between Egypt and Israel, a significant peace agreement."
    },
    {
      "date": "1979-03-28",
      "headline": "Three Mile Island Incident",
      "text": "Carter dealt with the Three Mile Island nuclear accident, the most serious in U.S. commercial nuclear power plant history."
    },
    {
      "date": "1980-11-04",
      "headline": "Presidential Election Defeat",
      "text": "Carter was defeated in his bid for re-election by Ronald Reagan."
    },
    {
      "date": "1981-01-20",
      "headline": "End of Presidency",
      "text": "Carter's term as president ended."
    },
    {
      "date": "1982",
      "headline": "Carter Center Founded",
      "text": "Carter founded the Carter Center, a non-profit organization aimed at advancing human rights and alleviating human suffering."
    },
    {
      "date": "2002-12-10",
      "headline": "Nobel Peace Prize",
      "text": "Carter was awarded the Nobel Peace Prize for his decades of untiring effort to find peaceful solutions to international conflicts, to advance democracy and human rights, and to promote economic and social development."
    },
    {
      "date": "2023-10-01",
      "headline": "100th Birthday",
      "text": "Jimmy Carter became the first U.S. president to live to 100 years of age."
    },
      {
      "date": "2024-12-29",
      "headline": "Death",
      "text": "Carter died at his home in Plains, Georgia, on December 29, 2024, at the age of 100."
    }
  ]
